CREATE OR REPLACE FUNCTION public.fn_method_value(p_method_key text, p_phrase text)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_kind text; v bigint;
begin
  select execution_kind into v_kind from public.gematria_methods where method_key = p_method_key;
  if v_kind is null then return null; end if;
  if v_kind in ('sql_function', 'context_activated') then
    return public.fn_dispatch_method(p_method_key, p_phrase);
  elsif v_kind = 'composite_engine' then
    select c.result::bigint into v from public.fn_composite_calc(p_method_key, p_phrase) c;
    return v;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_research_attach_existing_graph_node_v1(p_id uuid, p_target_node_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin boolean;
  v_actor text;
  v_row public.research_objects;
  v_target public.nodes;
  v_verification text;
  v_ledger_id uuid;
BEGIN
  SELECT (role = 'admin')
  INTO v_admin
  FROM public.users
  WHERE id = auth.uid();

  IF NOT coalesce(v_admin, false) THEN
    RAISE EXCEPTION 'admin only' USING ERRCODE = '42501';
  END IF;

  IF p_id IS NULL OR p_target_node_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_identity');
  END IF;

  v_actor := auth.uid()::text;

  SELECT *
  INTO v_row
  FROM public.research_objects
  WHERE id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'research_object_not_found');
  END IF;

  IF v_row.status <> 'canonical' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'canonical_required', 'status', v_row.status);
  END IF;

  IF v_row.privacy_scope <> 'public' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'public_source_required', 'privacy_scope', v_row.privacy_scope);
  END IF;

  IF v_row.meta #>> '{ext,extraction_integrity,fidelity_status}' = 'partial' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'partial_extraction_blocked');
  END IF;

  v_verification := v_row.engine_detail ->> 'verification_state';
  IF coalesce(v_verification, '') NOT IN ('match', 'match_numeric_only') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'verified_connection_required',
      'verification_state', v_verification
    );
  END IF;

  SELECT *
  INTO v_target
  FROM public.nodes
  WHERE id = p_target_node_id
    AND is_active = true
    AND type IN ('number', 'book')
    AND public.fn_graph_space_is_public(metadata)
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'active_public_target_required');
  END IF;

  IF v_row.promoted_node_id IS NOT NULL
     AND v_row.promoted_node_id <> p_target_node_id THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'existing_tree_target_conflict',
      'existing_target_node_id', v_row.promoted_node_id,
      'requested_target_node_id', p_target_node_id
    );
  END IF;

  UPDATE public.research_objects
  SET
    promoted_node_id = p_target_node_id,
    meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object(
      'governance',
      coalesce(meta -> 'governance', '{}'::jsonb) || jsonb_build_object(
        'tree_attachment',
        jsonb_build_object(
          'attached_by', v_actor,
          'attached_at', now(),
          'target_node_id', p_target_node_id,
          'target_node_type', v_target.type,
          'mode', 'existing_graph_identity_pointer',
          'contract', 'UNIVERSAL_RESEARCH_GRAPH_PROMOTION_CONTRACT_20260906',
          'human_gate_note', p_note
        )
      )
    )
  WHERE id = p_id;

  SELECT id
  INTO v_ledger_id
  FROM public.decision_ledger
  WHERE decision_type = 'research_graph_attach'
    AND subject_type = 'research_object'
    AND subject_ref = p_id::text
    AND human_decision = 'approve'
    AND status IN ('confirmed', 'applied', 'executed')
    AND candidate ->> 'target_node_id' = p_target_node_id::text
  ORDER BY created_at
  LIMIT 1;

  IF v_ledger_id IS NULL THEN
    INSERT INTO public.decision_ledger (
      decision_type, subject_type, subject_ref, candidate, domain,
      created_by_agent, agents_involved, human_decision, human_reason,
      decided_by, result_ref, provenance, status
    )
    VALUES (
      'research_graph_attach',
      'research_object',
      p_id::text,
      jsonb_build_object(
        'research_object_id', p_id,
        'target_node_id', p_target_node_id,
        'target_node_type', v_target.type,
        'verification_state', v_verification,
        'creates_node', false,
        'creates_edge', false
      ),
      'reality_graph',
      'GPT',
      ARRAY['GPT']::text[],
      'approve',
      p_note,
      v_actor,
      jsonb_build_object('research_object_id', p_id, 'promoted_node_id', p_target_node_id),
      jsonb_build_object(
        'triage_snapshot_date', '2026-10-22',
        'triage_base_commit', '640a385340733d84d4853e04e96cd38b3466e6ba',
        'selection', 'strength=חזק; recommendation=מתאים לעץ; contributor=צבי',
        'truth_score_created', false
      ),
      'executed'
    )
    RETURNING id INTO v_ledger_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'research_object_id', p_id,
    'status', v_row.status,
    'privacy_scope', v_row.privacy_scope,
    'verification_state', v_verification,
    'tree_attached', true,
    'target_node_id', p_target_node_id,
    'target_node_type', v_target.type,
    'decision_ledger_id', v_ledger_id,
    'created_node', false,
    'created_edge', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_research_review(p_id uuid, p_decision text, p_verification_state text DEFAULT NULL::text, p_ack_extraction_incomplete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin   boolean;
  r         public.research_objects;
  v_actor   text;
  v_detail  jsonb;
  v_vstate  text;
  v_prev    text;
  v_fid     text;
begin
  select (role='admin') into v_admin from public.users where id = auth.uid();
  if not coalesce(v_admin,false) then raise exception 'admin only'; end if;
  v_actor := auth.uid()::text;

  if p_decision not in ('approve','reject','canonicalize') then
    return jsonb_build_object('ok',false,'error','invalid_decision',
      'allowed', jsonb_build_array('approve','reject','canonicalize'));
  end if;

  if p_verification_state is not null
     and p_verification_state not in ('match','mismatch','method_unknown','not_tested') then
    return jsonb_build_object('ok',false,'error','invalid_verification_state',
      'allowed', jsonb_build_array('match','mismatch','method_unknown','not_tested'));
  end if;

  select * into r from public.research_objects where id = p_id for update;
  if not found then return jsonb_build_object('ok',false,'error','not found'); end if;

  if p_decision = 'reject' then
    if r.status not in ('candidate','approved') then
      return jsonb_build_object('ok',false,'error','invalid_transition',
        'from', r.status, 'to', 'rejected', 'allowed_from', jsonb_build_array('candidate','approved'));
    end if;
    update public.research_objects
       set status = 'rejected',
           meta = coalesce(meta,'{}'::jsonb) || jsonb_build_object(
                    'governance',
                    coalesce(meta->'governance','{}'::jsonb) || jsonb_build_object(
                      'rejected_by', v_actor, 'rejected_at', now(), 'rejected_from', r.status))
     where id = p_id;
    return jsonb_build_object('ok',true,'status','rejected','from',r.status);
  end if;

  if p_decision = 'approve' then
    if r.status <> 'candidate' then
      return jsonb_build_object('ok',false,'error','already_reviewed',
        'status', r.status, 'promoted_node_id', r.promoted_node_id);
    end if;
    update public.research_objects
       set status = 'approved',
           meta = coalesce(meta,'{}'::jsonb) || jsonb_build_object(
                    'governance',
                    coalesce(meta->'governance','{}'::jsonb) || jsonb_build_object(
                      'approved_by', v_actor, 'approved_at', now()))
     where id = p_id;
    return jsonb_build_object(
      'ok', true, 'status', 'approved', 'kind', r.kind,
      'graph_promoted', false, 'promoted_node_id', r.promoted_node_id,
      'note', 'approved != canonical (HG-2) — canonical promotion is a separate explicit Human-Gate act: p_decision=canonicalize'
    );
  end if;

  if r.status <> 'approved' then
    return jsonb_build_object('ok',false,'error','invalid_transition',
      'from', r.status, 'to', 'canonical', 'required_prior_state','approved');
  end if;

  v_fid := r.meta -> 'ext' -> 'extraction_integrity' ->> 'fidelity_status';
  if v_fid = 'partial' and coalesce(p_ack_extraction_incomplete, false) is not true then
    return jsonb_build_object(
      'ok', false, 'error', 'extraction_incomplete',
      'fidelity_status', v_fid,
      'extraction_integrity', r.meta -> 'ext' -> 'extraction_integrity',
      'status', r.status,
      'note', 'research_intake_foundation_contract §7.3 — ENGINE_VERIFIED arithmetic is not sufficient evidence that extraction succeeded. A materially claim-bearing element (semantic operand origin and/or source media reference) is missing or unresolved. Resolve it, or pass p_ack_extraction_incomplete=true to canonicalize deliberately; the acknowledgement is recorded as provenance. Nothing was changed by this call.'
    );
  end if;

  v_detail := coalesce(r.engine_detail, '{}'::jsonb);
  v_prev   := v_detail->>'verification_state';
  v_vstate := coalesce(p_verification_state, v_prev);

  if v_vstate is null then
    v_vstate := 'not_tested';
    v_detail := v_detail || jsonb_build_object(
      'verification_state', v_vstate,
      'verification_declared', jsonb_build_object(
        'declared_at', now(), 'declared_by', v_actor, 'at_transition', 'canonicalize',
        'reason', 'no_claim_vs_engine_test_on_record',
        'engine_verified_snapshot', r.engine_verified));
  elsif p_verification_state is not null and p_verification_state is distinct from v_prev then
    v_detail := v_detail || jsonb_build_object(
      'verification_state', v_vstate,
      'verification_declared', jsonb_build_object(
        'declared_at', now(), 'declared_by', v_actor, 'at_transition', 'canonicalize',
        'reason', 'human_gate_declared',
        'previous_verification_state', v_prev,
        'engine_verified_snapshot', r.engine_verified));
  end if;

  update public.research_objects
     set status = 'canonical',
         engine_detail = v_detail,
         meta = coalesce(meta,'{}'::jsonb) || jsonb_build_object(
                  'governance',
                  coalesce(meta->'governance','{}'::jsonb) || jsonb_build_object(
                    'canonicalized_by', v_actor, 'canonicalized_at', now(),
                    'canonicalized_from', 'approved',
                    'verification_state_at_canonicalization', v_vstate,
                    'extraction_fidelity_at_canonicalization', v_fid)
                  || case when v_fid = 'partial' and coalesce(p_ack_extraction_incomplete,false)
                       then jsonb_build_object('extraction_incomplete_ack',
                              jsonb_build_object('acknowledged_by', v_actor, 'acknowledged_at', now(),
                                                 'contract', 'research_intake_foundation_contract §7.3'))
                       else '{}'::jsonb end)
   where id = p_id;

  return jsonb_build_object(
    'ok', true, 'status', 'canonical', 'kind', r.kind,
    'privacy_scope', r.privacy_scope,
    'verification_state', v_vstate,
    'extraction_fidelity', v_fid,
    'extraction_incomplete_acknowledged', (v_fid = 'partial' and coalesce(p_ack_extraction_incomplete,false)),
    'graph_promoted', false,
    'graph_note', 'graph materialization is a separate, not-yet-built, explicit Human-Gate action (decision_ledger 40cb64c7) — canonicalize no longer creates nodes/edges',
    'insight_node', null, 'number_node', null,
    'promoted_node_id', r.promoted_node_id,
    'edge_id', null, 'decision_ledger_id', null,
    'published', false,
    'note', 'canonical != published (INVARIANT P1) — privacy_scope was not changed by this call'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_snapshot_research_object_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_changed text[] := '{}';
  v_material boolean := false;
begin
  if TG_OP = 'UPDATE' then
    if NEW.kind is distinct from OLD.kind then v_changed := array_append(v_changed, 'kind'); end if;
    if NEW.statement is distinct from OLD.statement then v_changed := array_append(v_changed, 'statement'); end if;
    if NEW.value is distinct from OLD.value then v_changed := array_append(v_changed, 'value'); end if;
    if NEW.terms is distinct from OLD.terms then v_changed := array_append(v_changed, 'terms'); end if;
    if NEW.relates is distinct from OLD.relates then v_changed := array_append(v_changed, 'relates'); end if;
    if NEW.source is distinct from OLD.source then v_changed := array_append(v_changed, 'source'); end if;
    if NEW.source_ref is distinct from OLD.source_ref then v_changed := array_append(v_changed, 'source_ref'); end if;
    if NEW.contributor is distinct from OLD.contributor then v_changed := array_append(v_changed, 'contributor'); end if;
    if NEW.confidence is distinct from OLD.confidence then v_changed := array_append(v_changed, 'confidence'); end if;
    if NEW.engine_verified is distinct from OLD.engine_verified then v_changed := array_append(v_changed, 'engine_verified'); end if;
    if NEW.engine_detail is distinct from OLD.engine_detail then v_changed := array_append(v_changed, 'engine_detail'); end if;
    if NEW.evidence is distinct from OLD.evidence then v_changed := array_append(v_changed, 'evidence'); end if;
    if NEW.status is distinct from OLD.status then v_changed := array_append(v_changed, 'status'); end if;
    if NEW.promoted_node_id is distinct from OLD.promoted_node_id then v_changed := array_append(v_changed, 'promoted_node_id'); end if;
    if NEW.parent_id is distinct from OLD.parent_id then v_changed := array_append(v_changed, 'parent_id'); end if;
    if NEW.meta is distinct from OLD.meta then v_changed := array_append(v_changed, 'meta'); end if;
    if NEW.owner_person_id is distinct from OLD.owner_person_id then v_changed := array_append(v_changed, 'owner_person_id'); end if;
    if NEW.privacy_scope is distinct from OLD.privacy_scope then v_changed := array_append(v_changed, 'privacy_scope'); end if;

    if OLD.kind in ('fact','relation','observation') and OLD.status in ('approved','canonical') then
      if (NEW.statement is distinct from OLD.statement
            and public.fn_research_claim_uid(NEW.statement) is distinct from public.fn_research_claim_uid(OLD.statement))
         or NEW.value is distinct from OLD.value
         or NEW.terms is distinct from OLD.terms
         or NEW.relates is distinct from OLD.relates
      then
        v_material := true;
      end if;
    end if;

    if v_material and coalesce(current_setting('app.allow_claim_correction', true), '') is distinct from 'on' then
      raise exception 'material_change_requires_correction_rpc: an approved/canonical fact or relation''s statement/value/terms/relates cannot be updated directly (id=%). Use public.fn_research_object_correct() to create a governed successor instead.', OLD.id;
    end if;

    insert into public.research_object_revisions
      (research_object_id, research_object_source_uid, research_object_claim_uid,
       change_kind, changed_fields, before_snapshot, statement_before,
       actor, actor_fallback, occurred_at)
    values
      (OLD.id, public.fn_research_source_uid(OLD.source_ref), public.fn_research_claim_uid(OLD.statement),
       'update', v_changed, to_jsonb(OLD), OLD.statement,
       auth.uid(), session_user, now());

    return NEW;

  elsif TG_OP = 'DELETE' then
    insert into public.research_object_revisions
      (research_object_id, research_object_source_uid, research_object_claim_uid,
       change_kind, changed_fields, before_snapshot, statement_before,
       actor, actor_fallback, occurred_at)
    values
      (OLD.id, public.fn_research_source_uid(OLD.source_ref), public.fn_research_claim_uid(OLD.statement),
       'delete', '{}', to_jsonb(OLD), OLD.statement,
       auth.uid(), session_user, now());

    return OLD;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_zvi_standing_approve_research_object()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ref text;
  v_source_id uuid;
  v_contribution_id uuid;
  v_authorized boolean := false;
begin
  if new.status is distinct from 'candidate' then
    return new;
  end if;

  v_ref := coalesce(new.source_ref,'');

  -- Canonical WhatsApp/channel source.
  if v_ref ~* '^channel_updates:[0-9a-f-]{36}' then
    begin
      v_source_id := substring(v_ref from '^channel_updates:([0-9a-fA-F-]{36})')::uuid;
      select exists(
        select 1
        from public.channel_updates cu
        where cu.id = v_source_id
          and (
            cu.contributor_id = 'c66f0464-0928-490e-be9b-66d8a87e7fc8'::uuid
            or (cu.contributor_id is null and cu.credit = 'צבי (OPOC)')
          )
      ) into v_authorized;
    exception when invalid_text_representation then
      v_authorized := false;
    end;
  end if;

  -- Canonical Research Contribution source, if/when a projection uses this source_ref family.
  if not v_authorized and v_ref ~* '^research_contributions:[0-9a-f-]{36}' then
    begin
      v_contribution_id := substring(v_ref from '^research_contributions:([0-9a-fA-F-]{36})')::uuid;
      select exists(
        select 1
        from public.research_contributions rc
        where rc.id = v_contribution_id
          and (
            rc.author_contributor_id = 'c66f0464-0928-490e-be9b-66d8a87e7fc8'::uuid
            or rc.author_user_id = '24be4fb3-59f2-4cdf-ad86-47d8a43f274e'::uuid
          )
      ) into v_authorized;
    exception when invalid_text_representation then
      v_authorized := false;
    end;
  end if;

  if v_authorized then
    new.status := 'approved';
    new.meta := coalesce(new.meta,'{}'::jsonb) || jsonb_build_object(
      'governance',
      coalesce(new.meta->'governance','{}'::jsonb) || jsonb_build_object(
        'standing_approval', true,
        'standing_approval_rule', 'writer_material_home_law v5',
        'standing_approval_subject', 'c66f0464-0928-490e-be9b-66d8a87e7fc8',
        'human_gate', 'ZURIEL',
        'approved_at', now(),
        'verification_preserved', true,
        'canonicalized', false,
        'published', false
      )
    );
  end if;

  return new;
end;
$function$
